@page "/recipes/{CuisineId:int}"
@rendermode InteractiveServer
@using sv_822820dc83674b1188b44920deb99628.Services
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p><em>Loading recipes…</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p><em>Refreshing…</em></p>
    }

    <table class="table">
        <thead>
            <tr>
                <th>Title</th>
                <th>Description</th>
                <th>Prep Time (min)</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var recipe in DisplayedRecipes)
            {
                <tr>
                    <td>@recipe.Title</td>
                    <td>@recipe.Description</td>
                    <td>@recipe.PrepTimeMinutes</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private bool _isRefreshing;
    private string? _error;

    private CancellationTokenSource? _loadCts;
    private readonly CancellationTokenSource _disposeCts = new();

    private int _lastLoadedCuisineId;

    private IEnumerable<Recipe> DisplayedRecipes
    {
        get
        {
            if (_recipes is null) return Enumerable.Empty<Recipe>();
            return Sort?.ToLowerInvariant() switch
            {
                "newest" => _recipes.OrderByDescending(r => r.Id),
                "popular" => _recipes.OrderBy(r => r.PrepTimeMinutes),
                _ => _recipes,
            };
        }
    }

    protected override Task OnInitializedAsync()
    {
        _lastLoadedCuisineId = CuisineId;
        return LoadRecipesAsync();
    }

    public override Task SetParametersAsync(ParameterView parameters)
    {
        // Capture old CuisineId before base applies the new values.
        var previousCuisineId = CuisineId;
        return base.SetParametersAsync(parameters)
            .ContinueWith(_ =>
            {
                // Only reload if cuisine actually changed (not sort).
                if (CuisineId != previousCuisineId && CuisineId != _lastLoadedCuisineId)
                {
                    _lastLoadedCuisineId = CuisineId;
                    _ = InvokeAsync(() => LoadRecipesAsync());
                }
            }, TaskScheduler.Current);
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight load.
        _loadCts?.Cancel();
        _loadCts?.Dispose();
        _loadCts = CancellationTokenSource.CreateLinkedTokenSource(_disposeCts.Token);

        var token = _loadCts.Token;

        _error = null;
        _isRefreshing = _recipes is not null;
        StateHasChanged();

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, token);

            if (token.IsCancellationRequested) return;

            _recipes = results;
            _isRefreshing = false;
            _error = null;
        }
        catch (OperationCanceledException) when (token.IsCancellationRequested)
        {
            // Expected when navigating away or changing cuisine — do nothing.
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _isRefreshing = false;
            _error = "Something went wrong loading recipes. Please try again.";
        }

        StateHasChanged();
    }

    private Task RetryAsync() => LoadRecipesAsync();

    public void Dispose()
    {
        _disposeCts.Cancel();
        _disposeCts.Dispose();
        _loadCts?.Cancel();
        _loadCts?.Dispose();
    }
}

